generated_pydough:
most_common_characteristic = product_characteristic.CALCULATE(
    char_name=characteristic.characteristic_name
).PARTITION(
    name="char_groups",
    by=(char_name)
).CALCULATE(
    characteristic_name=char_name,
    occurrence_count=COUNT(product_characteristic)
).TOP_K(1, by=occurrence_count.DESC()).CALCULATE(
    name=characteristic_name
)

result = shops.CALCULATE(
    shop_name=shop_name, # Get the name of the shop
    total_quantity=SUM(stocks.quantity) # Calculate the total quantity for each shop by summing quantities in its 'stocks' sub-collection
).TOP_K(
    1, # Get only the top 1 shop
    by=total_quantity.DESC() # Order by total_quantity in descending order to find the greatest
).CALCULATE(
    shop_name=shop_name # Select only the shop_name as the final output
)

most_papers_inst = insts.CALCULATE(
    num_papers=COUNT(authorships.paper)
).TOP_K(1, by=num_papers.DESC()).CALCULATE(
    institution_name=name
)

party_delegates = elections.CALCULATE(
    party_name=party_join.party
).PARTITION(
    name="party_groups",
    by=(party_name)
).CALCULATE(
    party_name=party_name,
    num_delegates=COUNT(elections)
).TOP_K(1, by=num_delegates.DESC())

most_popular_scholarship_sport = sportsinfos.WHERE(
    onscholarship == 'Yes'
).PARTITION(
    name="sports_groups", by=sportname
).CALCULATE(
    sport_name=sportname,
    num_students_on_scholarship=COUNT(sportsinfos)
).TOP_K(1, by=num_students_on_scholarship.DESC())

characteristic_counts = product_characteristic.CALCULATE(
    characteristic_name=characteristic.characteristic_name
).PARTITION(
    name="characteristics_group",
    by=characteristic_name
).CALCULATE(
    characteristic_name=characteristic_name,
    char_count=COUNT(product_characteristic)
)

most_common_characteristic = characteristic_counts.TOP_K(
    1,
    by=char_count.DESC()
).CALCULATE(
    characteristic_name=characteristic_name
)

average_ratings_for_filtered_movies = movies.WHERE(
    HASNOT(ratings.WHERE(reviewer.name == 'Brittany Harris')) & HAS(ratings)
).CALCULATE(
    movie_id=mid,
    average_rating=AVG(ratings.stars)
)

shop_with_greatest_quantity = shops.CALCULATE(
    shop_name=shop_name,
    total_stock_quantity=SUM(stocks.quantity)
).TOP_K(1, by=total_stock_quantity.DESC()).CALCULATE(
    shop_name=shop_name
)

most_papers_institution = insts.CALCULATE(
    inst_name=name,
    paper_count=COUNT(authorships.paper)
).TOP_K(1, by=paper_count.DESC()).CALCULATE(
    inst_name=inst_name
)

lowest_cost_treatment_type_description = dog_kennels.treatment_type.CALCULATE(
    treatment_type_description=treatment_type_description,
    total_cost=SUM(treatment.cost_of_treatment)
).TOP_K(1, by=total_cost.ASC()).CALCULATE(
    description=treatment_type_description
)

instructor_with_most_courses_building = faculties.CALCULATE(
    num_courses=COUNT(courses)
).TOP_K(1, by=[num_courses.DESC(), building.ASC()]).CALCULATE(
    building=building
)
